quiz:[{q:"Was ist die Rolle von Best Prime?",a:["Technologieplattform","Vertriebs- und Community-Organisation"]},{q:"Was ist ePOINT?",a:["Händler- und Kundenökosystem mit kostenloser Cashback-App","Klassische Bank"]},{q:"Was ist ePAY im Gesamtbild?",a:["Die geplante Payment- und Transaktionsebene (Start geplant 09.01.2027)","Eine Recruiting-App"]},{q:"Kannst du den Nutzen getrennt für Kunde, Händler und Partner erklären?",a:["Ja, frei und verständlich","Noch nicht sicher"]}],
