 say:[["„Verdient wird nach dem offiziellen Plan – einmalig an Abschlüssen, laufend an der Nutzung.“","„Damit verdienst du 2.000 € im Monat.“ · „passives Einkommen“"],["„Die App ist kostenlos. Cashback gibt es bei teilnehmenden Händlern und Shops.“","„Du bekommst bei jedem Einkauf Geld zurück.“"],["„ePAY ist für den 09.01.2027 geplant.“","„ePAY ist fertig“ oder „garantiert“"],["„Best Prime mit der Plattform ePOINT.“ – sofort, wenn jemand direkt fragt","Ausweichen, wenn jemand nach der Firma fragt"],["„Entscheide in Ruhe.“","„Nur noch heute.“ · „Die Plätze sind fast weg.“ – wenn es nicht stimmt"],["„Das weiß ich nicht, ich kläre es bis [Datum].“","Erfundene Zahlen, alte Screenshots, Gerüchte"],["„Das Rechenbeispiel ist ein Modell, keine Prognose.“","Duplikationsrechnungen als Wachstumsversprechen"]],
